(function () {
  if (document.getElementById('az-desk-journal')) return;
  const st = document.createElement('style'); st.id = 'az-desk-journal';
  st.textContent = '@media (min-width:1000px) and (min-height:600px){body.navon #w-map:has(#qsheet[hidden]) .journal{grid-row:1 / 3}body.navon #w-map .az-desktop-guide{display:none!important}}';
